#include <stdio.h>


int main(void)
{
    int frames[] = {3, 2, 1};
    int top = 2;
    int result = 1;
    while (top >= 0) {
        result *= frames[top--];
    }
    printf("%d\n", result);
    return 0;
}

#include <stdio.h>


int main(void)
{
    int moves = 0;
    for (int n = 1; n <= 3; n++) {
        moves = 2 * moves + 1;
    }
    printf("%d\n", moves);
    return 0;
}

